package ncasa.shoppinglist.application;
import java.time.Clock;import java.util.*;import ncasa.shoppinglist.application.port.out.*;import ncasa.shoppinglist.domain.*;
public final class ShoppingItemLifecycleUseCase{private final ShoppingListRepository lists;private final ShoppingItemRepository items;private final ShoppingListHouseholdAccessPort access;private final Clock clock;public ShoppingItemLifecycleUseCase(ShoppingListRepository l,ShoppingItemRepository i,ShoppingListHouseholdAccessPort a,Clock c){lists=l;items=i;access=a;clock=c;}public ShoppingItem purchase(Long actor,UUID h,UUID l,UUID id,long v){var ctx=access.getContext(h,actor);active(h,l);var item=UpdateShoppingItemUseCase.load(items,id,l);UpdateShoppingItemUseCase.check(item,v);item.purchase(ctx.actorMemberId(),clock.instant());var saved=items.save(item);changed(l);return saved;}public ShoppingItem reopen(Long actor,UUID h,UUID l,UUID id,long v){access.getContext(h,actor);active(h,l);var item=UpdateShoppingItemUseCase.load(items,id,l);UpdateShoppingItemUseCase.check(item,v);item.reopen(items.nextPendingPosition(l),clock.instant());var saved=items.save(item);changed(l);return saved;}public void delete(Long actor,UUID h,UUID l,UUID id,long v){access.getContext(h,actor);active(h,l);var item=UpdateShoppingItemUseCase.load(items,id,l);UpdateShoppingItemUseCase.check(item,v);items.delete(item);changed(l);}public int clearPurchased(Long actor,UUID h,UUID l,long revision){access.getContext(h,actor);active(h,l);if(!lists.advanceContentRevision(l,revision,clock.instant()))throw new ShoppingListConflictException("Shopping list content changed concurrently");return items.deletePurchased(l);}private ShoppingList active(UUID h,UUID l){var value=GetShoppingListUseCase.load(lists,l,h);value.requireActive();return value;}private void changed(UUID listId){lists.touchContent(listId,clock.instant());}}
